<?php
require_once __DIR__.'/includes/functions.php';$user=require_login();if(!in_array($user['role_code'],['admin_simrs','radiologi','dokter','dokter_umum','dokter_igd','perawat','igd','rekammedis'],true)){http_response_code(403);exit('Akses berkas radiologi ditolak.');}$id=(int)($_GET['id']??0);$q=db()->prepare('SELECT ra.stored_name,ra.original_name,ra.mime_type,o.registration_id FROM radiology_attachments ra JOIN radiology_orders ro ON ro.id=ra.radiology_order_id JOIN orders o ON o.id=ro.order_id WHERE ra.id=?');$q->execute([$id]);$f=$q->fetch();if(!$f){http_response_code(404);exit('Berkas tidak ditemukan.');}if(!is_admin($user)&&$user['role_code']!=='radiologi'){require_patient_registration($user,(int)$f['registration_id'],'history');}$path=__DIR__.'/private_uploads/'.$f['stored_name'];if(!is_file($path)){http_response_code(404);exit('File tidak tersedia.');}header('Content-Type: '.$f['mime_type']);header('Content-Disposition: inline; filename="'.rawurlencode($f['original_name']).'"');header('X-Content-Type-Options: nosniff');readfile($path);
